// @story:113
// @ac:1
// @design:D10
// @type:functional
// @technique:state-transition
test("AC-1 Adding a product from the list changes its button to Remove and the cart badge shows the count", async ({ page }) => {
  const productListPage = new ProductListPage(page);

  await test.step("Given I am on the sign-in page", async () => {
    await productListPage.goto();
  });

  await test.step("When I sign in", async () => {
    await productListPage.usernameInput.fill(process.env["AQA_APP_USER"] ?? "standard_user");
    await productListPage.passwordInput.fill(process.env["AQA_APP_PASS"] ?? "secret_sauce");
    await productListPage.loginButton.click();
  });

  await test.step("Then the product list is shown", async () => {
    await expect(page.getByText("Products").first()).toBeVisible();
  });

  await test.step("And the first product shows 'Add to cart' (precondition)", async () => {
    await expect(page.getByTestId("add-to-cart").first()).toBeVisible();
  });

  await test.step("When I click the first 'Add to cart' button in the product list", async () => {
    await page.getByTestId("add-to-cart").first().click();
  });

  await test.step("Then the first product in the list shows 'Remove'", async () => {
    await expect(page.getByTestId("remove").first()).toBeVisible();
  });

  await test.step("And the cart badge shows '1'", async () => {
    await expect(page.getByTestId("shopping-cart-badge")).toHaveText("1");
  });
});

